<body>
<canvas id="game" width="224" height="288"></canvas>
<script>
"use strict";

/*
  Galaga-style clone in one file.

  Internal resolution is 224 x 288, scaled with CSS to fit the window.
  Game logic runs at a fixed 60 Hz timestep; rendering runs once per animation frame.
*/

/* ------------------------------------------------------------------ */
/* Canvas and scaling                                                 */
/* ------------------------------------------------------------------ */

const W = 224;
const H = 288;
const DT = 1 / 60;

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
ctx.imageSmoothingEnabled = false;

function fitCanvas() {
  const maxW = Math.max(1, Math.floor(window.innerWidth / W));
  const maxH = Math.max(1, Math.floor(window.innerHeight / H));
  let scale = Math.min(maxW, maxH);
  if (scale < 1) {
    // If the window is smaller than the native resolution, use a fractional CSS scale.
    scale = Math.min(window.innerWidth / W, window.innerHeight / H);
  }
  canvas.style.width = Math.floor(W * scale) + "px";
  canvas.style.height = Math.floor(H * scale) + "px";
}
window.addEventListener("resize", fitCanvas);
fitCanvas();

/* ------------------------------------------------------------------ */
/* Pixel font                                                         */
/* ------------------------------------------------------------------ */

const FONT = {
  " ": ["00000","00000","00000","00000","00000","00000","00000"],
  "A": ["01110","10001","10001","11111","10001","10001","10001"],
  "B": ["11110","10001","10001","11110","10001","10001","11110"],
  "C": ["01110","10001","10000","10000","10000","10001","01110"],
  "D": ["11100","10001","10001","10001","10001","10001","11100"],
  "E": ["11111","10000","10000","11110","10000","10000","11111"],
  "F": ["11111","10000","10000","11110","10000","10000","10000"],
  "G": ["01110","10000","10000","10111","10001","10001","01110"],
  "H": ["10001","10001","10001","11111","10001","10001","10001"],
  "I": ["11111","01010","01010","01010","01010","01010","11111"],
  "J": ["00111","00010","00010","00010","10010","10010","01100"],
  "K": ["10001","10010","10100","11000","10100","10010","10001"],
  "L": ["10000","10000","10000","10000","10000","10000","11111"],
  "M": ["10001","11011","10101","10101","10001","10001","10001"],
  "N": ["10001","11001","11001","10101","10011","10011","10001"],
  "O": ["01110","10001","10001","10001","10001","10001","01110"],
  "P": ["11110","10001","10001","11110","10000","10000","10000"],
  "Q": ["01110","10001","10001","10001","10101","10010","01101"],
  "R": ["11110","10001","10001","11110","10100","10010","10001"],
  "S": ["01110","10001","10000","01110","00001","10001","01110"],
  "T": ["11111","01010","01010","01010","01010","01010","01010"],
  "U": ["10001","10001","10001","10001","10001","10001","01110"],
  "V": ["10001","10001","10001","10001","01010","01010","00100"],
  "W": ["10001","10001","10101","10101","10101","11011","10001"],
  "X": ["10001","10001","01010","00100","01010","10001","10001"],
  "Y": ["10001","10001","01010","00100","00100","00100","00100"],
  "Z": ["11111","00001","00010","00100","01000","10000","11111"],
  "0": ["01110","10001","10011","10101","11001","10001","01110"],
  "1": ["00100","01100","00100","00100","00100","00100","01110"],
  "2": ["01110","10001","00001","00010","00100","01000","11111"],
  "3": ["11110","00001","00001","01110","00001","00001","11110"],
  "4": ["10010","10010","10010","11111","00010","00010","00010"],
  "5": ["11111","10000","11110","00001","00001","10001","01110"],
  "6": ["00110","01000","10000","11110","10001","10001","01110"],
  "7": ["11111","00001","00010","00100","01000","01000","01000"],
  "8": ["01110","10001","10001","01110","10001","10001","01110"],
  "9": ["01110","10001","10001","01111","00001","00010","01100"],
  "!": ["00100","00100","00100","00100","00100","00000","00100"],
  ":": ["00000","00000","00100","00000","00100","00000","00000"],
  ".": ["00000","00000","00000","00000","00000","00000","00100"],
  "-": ["00000","00000","00000","11111","00000","00000","00000"],
  "/": ["00001","00010","00100","01000","10000","00000","00000"],
  "%": ["11001","10010","00100","00100","00100","01001","10011"],
  "?": ["01110","10001","00001","00110","00100","00000","00100"]
};

const FONT_MASKS = {};
for (const ch in FONT) {
  FONT_MASKS[ch] = FONT[ch].map(row => {
    let m = 0;
    for (let x = 0; x < 5; x++) {
      if (row[x] === "1") m |= (1 << x);
    }
    return m;
  });
}

function textWidth(text, scale = 1) {
  return Math.max(0, text.length * 6 * scale - scale);
}

function drawText(text, x, y, color, scale = 1) {
  text = String(text).toUpperCase();
  ctx.fillStyle = color;
  let cx = x;
  for (let i = 0; i < text.length; i++) {
    const mask = FONT_MASKS[text[i]] || FONT_MASKS["?"];
    for (let r = 0; r < 7; r++) {
      const row = mask[r];
      if (!row) continue;
      for (let c = 0; c < 5; c++) {
        if (row & (1 << c)) {
          ctx.fillRect(cx + c * scale, y + r * scale, scale, scale);
        }
      }
    }
    cx += 6 * scale;
  }
}

function drawTextCenter(text, centerX, y, color, scale = 1) {
  drawText(text, Math.round(centerX - textWidth(text, scale) / 2), y, color, scale);
}

/* ------------------------------------------------------------------ */
/* Sprites                                                            */
/* ------------------------------------------------------------------ */

const PLAYER_ROWS = [
