    "................"
  ]
];

const GOEI_ROWS = [
  [
    "................",
    "....RR....RR....",
    "...RRRR..RRRR...",
    "..RRRRRRRRRRRR..",
    ".RRRRRWWWWRRRRR.",
    ".RRRRWWWWWWRRRR.",
    ".RRRRWWWWWWRRRR.",
    ".RRRRRWWWWRRRRR.",
    "..RRRRRRRRRRRR..",
    "...RRRR..RRRR...",
    "....RR....RR....",
    "................",
    "................",
    "................",
    "................",
    "................"
  ],
  [
    "................",
    "................",
    "....RR....RR....",
    "...RRRR..RRRR...",
    "..RRRRRRRRRRRR..",
    ".RRRRRWWWWRRRRR.",
    ".RRRRWWWWWWRRRR.",
    ".RRRRWWWWWWRRRR.",
    ".RRRRRWWWWRRRRR.",
    "..RRRRRRRRRRRR..",
    "...RRRR..RRRR...",
    "....RR....RR....",
    "................",
    "................",
    "................",
    "................"
  ]
];

const BOSS_ROWS = [
  [
    "................",
    "......GGGG......",
    "....GGGGGGGG....",
    ".GGGGGGGGGGGGGG.",
    "GGGGGGWWWWGGGGGG",
    "GGGGGWWWWWWGGGGG",
    "GGGGGWWWWWWGGGGG",
    "GGGGGGWWWWGGGGGG",
    ".GGGGGGGGGGGGGG.",
    "....GGGGGGGG....",
    "......GGGG......",
    "................",
    "................",
    "................",
